    visa2_req2: "Establecer vínculos económicos (empleo, negocio, o depósito bancario de $5,000+)",
    visa2_req3: "Pasaporte válido y antecedentes penales",
    visa2_req4: "Prueba de actividad profesional o económica en Panamá",
